const items = $input.all();
if (!items || items.length === 0) return [];

return items.map(item => {
  const row = item.json;
  const stage = Number(row.lifecycle_stage || 0);

  let segmentAlias = null;
  if (stage === 1) segmentAlias = 'ac-nurture-phase-b';
  else if (stage === 2) segmentAlias = 'ac-nurture-phase-c';
  else if (stage === 3) segmentAlias = 'ac-nurture-phase-d';

  return {
    json: {
      contact_id: row.contact_id,
      lead_hash: row.lead_hash,
      lifecycle_stage: stage,
      segmentAlias,
      last_video_at: row.last_video_at
    }
  };
}).filter(item => item.json.segmentAlias !== null);

const contactsResponse = $json;
const contacts = Object.values(contactsResponse.contacts || {});
if (!contacts.length) return [];

const contact = contacts[0];
return [{
  json: {
    ...$('Code - Map Stage to Segment').item.json,
    mauticContactId: contact.id
  }
}];
